mapper.sql:
project_scope_nodes AS ( SELECT t.root_project_id, t.tree_version, t.descendant_project_id AS project_id FROM proj_project_tree_path t WHERE t.tenant_id = #{query.tenantId} AND t.deleted = b'0' AND t.ancestor_project_id = t.root_project_id
AND (t.root_project_id, t.tree_version) IN
(#{tree.rootProjectId}, #{tree.treeVersion})
AND 1 = 0
), project_scope_grants AS (
SELECT NULL AS resource_id, NULL AS scope_code WHERE 1 = 0
), visible_projects AS (
SELECT DISTINCT p.id AS project_id FROM proj_project p WHERE p.tenant_id = #{query.tenantId} AND p.deleted = b'0'
SELECT DISTINCT n.project_id FROM project_scope_nodes n WHERE n.project_id = #{query.readScope.projectScope.officeReadonlyProjectId}
SELECT DISTINCT n.project_id FROM project_scope_nodes n
WHERE EXISTS ( SELECT 1 FROM proj_project_member_assignment m WHERE m.tenant_id = #{query.tenantId} AND m.deleted = b'0' AND m.project_id = n.project_id AND m.user_id = #{query.readScope.projectScope.subjectUserId} AND m.status = 'ACTIVE' AND m.authorization_confirmed = b'1' AND (m.effective_from IS NULL OR m.effective_from <= #{query.readScope.projectScope.effectiveAt}) AND (m.effective_to IS NULL OR m.effective_to > #{query.readScope.projectScope.effectiveAt}) ) OR EXISTS ( SELECT 1 FROM proj_project p WHERE p.tenant_id = #{query.tenantId} AND p.deleted = b'0' AND p.id = n.project_id
AND (
(p.company_id=#{scope.companyId} AND p.department_id=#{scope.departmentId})
)
AND 1=0
) OR EXISTS ( SELECT 1 FROM proj_project p WHERE p.tenant_id = #{query.tenantId} AND p.deleted = b'0' AND p.id = n.project_id AND p.creator = #{query.readScope.projectScope.creator} ) OR EXISTS ( SELECT 1 FROM project_scope_grants g WHERE g.scope_code = 'CURRENT_PROJECT' AND g.resource_id = n.project_id ) OR EXISTS ( SELECT 1 FROM project_scope_grants g JOIN project_scope_nodes a ON a.project_id = g.resource_id AND a.root_project_id = n.root_project_id AND a.tree_version = n.tree_version JOIN proj_project_tree_path t ON t.tenant_id = #{query.tenantId} AND t.root_project_id = n.root_project_id AND t.tree_version = n.tree_version AND t.ancestor_project_id = a.project_id AND t.descendant_project_id = n.project_id AND t.deleted = b'0' WHERE g.scope_code = 'PROJECT_AND_DESCENDANTS' )
SELECT NULL AS project_id WHERE 1 = 0
)
